@Path("/")
@Controller
@Produces(MediaType.TEXT_HTML)
public class BoFrontUserController {


    private static final String USER_LIST_PAGE = "/frontuser/userList";

    @Resource
    BoFrontUserManager boFrontUserManager;

    @GET
